// src/hooks/UseNotifications.js
import { useCallback, useEffect, useMemo, useState } from 'react';
import { fetchAlerts, fetchAlertDetail, fetchAlertStats } from '../api/NotificationsApi';

/**
 * useNotifications
 * - 기존 페이지들이 useNotifications(100) 형태(=limit)를 기대하므로
 *   숫자 인자를 넣으면 {limit,size}로 동작하게 호환 처리한다.
 * - 동시에 페이지형(필터 포함)도 지원.
 */
export function useNotifications(initial = 100) {
  const initialObj = useMemo(() => {
    if (typeof initial === 'number') {
      return { page: 1, size: Number(initial) || 100 };
    }
    return initial || {};
  }, [initial]);

  const [page, setPage] = useState(initialObj.page ?? 1);
  const [size, setSize] = useState(initialObj.size ?? 20);

  const [keyword, setKeyword] = useState(initialObj.keyword ?? '');
  const [level, setLevel] = useState(initialObj.level ?? 'ALL'); // ALL | DANGER | WARNING | SAFE
  const [from, setFrom] = useState(initialObj.from ?? '');
  const [to, setTo] = useState(initialObj.to ?? '');
  const [sort, setSort] = useState(initialObj.sort ?? 'collectedAt,desc');

  const [items, setItems] = useState([]);
  const [total, setTotal] = useState(0);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetchAlerts({
        page,
        size,
        keyword,
        level: level === 'ALL' ? '' : level,
        from,
        to,
        sort,
      });
      setItems(res?.items || []);
      setTotal(res?.total || 0);
    } catch (e) {
      setError(e);
      setItems([]);
      setTotal(0);
    } finally {
      setLoading(false);
    }
  }, [page, size, keyword, level, from, to, sort]);

  useEffect(() => {
    load();
  }, [load]);

  // ✅ 기존 NotificationPage가 기대하는 limit/setLimit 호환
  const limit = size;
  const setLimit = (v) => setSize(Number(v) || 20);

  return {
    notifications: items,
    total,
    loading,
    error,

    // paging
    page,
    setPage,
    size,
    setSize,

    // legacy alias
    limit,
    setLimit,

    // filters
    keyword,
    setKeyword,
    level,
    setLevel,
    from,
    setFrom,
    to,
    setTo,
    sort,
    setSort,

    refresh: load,

    fetchAlertDetail,
    fetchAlertStats,
  };
}
